from typing import Callable, Iterable, TypeVar
T = TypeVar("T")
def iterate(f: Callable[[T], T], x: T, n: int) -> T:
    if n < 0: raise ValueError("n must be nonnegative")
    for _ in range(n): x = f(x)
    return x
def check_depth(states: Iterable[T], encode: Callable[[T], T], inspect: Callable[[T], T], n: int) -> bool:
    return all(iterate(inspect, iterate(encode, x, n), n) == x for x in states)
if __name__ == "__main__":
    e = lambda s: (s[0], s[1] + 1)
    i = lambda s: (s[0], s[1] - 1)
    states = [(x, 0) for x in range(-5, 6)]
    for n in [0, 1, 2, 3, 10, 100]: print(n, check_depth(states, e, i, n))

from typing import Callable, Hashable, Optional, TypeVar
T = TypeVar("T", bound=Hashable)
def first_return(f: Callable[[T], T], x: T, bound: int) -> Optional[int]:
    if bound < 1: raise ValueError("bound must be positive")
    y = x
    for k in range(1, bound + 1):
        y = f(y)
        if y == x: return k
    return None
if __name__ == "__main__":
    for modulus in range(1, 9):
        period = first_return(lambda x, m=modulus: (x + 1) % m, 0, 20)
        print(f"rotation modulo {modulus}: first return {period}")

